@router.post("/mfa/challenges/{challenge_id}/verify")
@limiter.limit("3/minute")
def verify_mfa_challenge(
    request: Request,
    challenge_id: str,
    body: MfaVerificationRequest,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    challenge = db.query(MfaChallenge).filter(
        MfaChallenge.id == challenge_id,
        MfaChallenge.user_id == user.id
    ).first()
    if not challenge or challenge.is_expired:
        raise HTTPException(status_code=400, detail="Challenge expired or invalid")

    if not verify_totp(challenge.secret, body.code):
        raise HTTPException(status_code=400, detail="Incorrect authentication code")

    challenge.status = "verified"
    db.commit()
    return {"status": "mfa_verified"}
